function UIMainBattleChapterRewardPopupDialog:Awake()
    self.ControlTrans = self.ImgCgDetails.transform.parent:Find("Control")
    self:InitData()
    SetButtonAction(self.BtnArrowLeft, function()
        --向左切
        self.curIndex = self.curIndex - 1
        if self.curIndex <= 0 then
            self.curIndex = 1
        end
        ---@type ChapterVo
        local vo = self.chapters[self.curIndex]
        self.curChapterId = vo.id
        self:FillSelf()
    end)
    SetButtonAction(self.BtnArrowRight, function()
        ---向右切
        self.curIndex = self.curIndex + 1
        if self.curIndex >= #self.chapters then
            self.curIndex = #self.chapters
        end
        ---@type ChapterVo
        local vo = self.chapters[self.curIndex]
        self.curChapterId = vo.id
        self:FillSelf()
    end)

    SetButtonAction(self.BtnReceive, function()
        ---领取按钮的逻辑
        local t = QuestConfMgr:GetInstance():GetCanDrawChapterRewardIds()
        if not t or table.count(t) <= 0 then
            GameUtils.Toast(localize("当前无奖励可领取"))
            return
        end

        local goodsId = string.split(self.controller.goodIds, ";")
        ---@type QuestComponent
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
        comp:ChapterRewardDrawReq(self.curChapterId, function(rewards)
            self:FillSelf()
            Events.Broadcast(Constants.EventNames.MainQuestChapterRewardChange)
            for i, v in pairs(rewards) do
                for i, gId in pairs(goodsId) do
                    if checkNumber(v.goodsId) == checkNumber(gId) then
                        GameUtils.StartFlyGoods(self.CommonGoodsListLight.gameObject, checkNumber(v.goodsId))
                    end
                end
            end
        end)
    end)
    SetButtonAction(self.ControlTrans:Find("Menu/BtnUIControl"), function()
        CfUtils.SetActive(self.ControlTrans, false)
    end)
    SetButtonAction(self.ControlTrans:Find("Menu/BtnSkip"), function()
        self.startPlaying = false
        self.isPlayPlot = false
        CfUtils.SetActive(self.ImgCgDetails.transform.parent, false)
        UINavigationBarRoot.Instance:SetActive(true)
    end)
    SetButtonAction(self.ControlTrans:Find("Menu/BtnPlay"), function()
        ---开始播放
        self.startPlaying = true
    end)
    SetButtonAction(self.ImgCgDetails, function()
        if self.selectData and checkNumber(self.selectData.cgType) ~= CG_TYPE.OnlyPicture then
            CfUtils.SetActive(self.ControlTrans:Find("Menu/BtnPlay"), true)
        end
        CfUtils.SetActive(self.ControlTrans, true)
    end)
end

function UIMainBattleChapterRewardPopupDialog:InitData()
    local t = CfUtils.GetCf(AutoIds.IdSetting281, "ChapterVo", true)
    self.chapters = checkTable(t)
    self.maxChapterNo = checkNumber(table.takeLast(self.chapters).number)
    ---当前最新的关卡id
    self.newestChapterId = QuestConfMgr:GetInstance():GetCurChapterId()
    self.curChapterId = self.newestChapterId
    --print("==>>", table.dump(self.chapters, false, 2))
    --print('--->>', self.curChapterId, self.newestChapterId)
    ---@type QuestConfMgr
    local questConfMgr = QuestConfMgr:GetInstance()
    local parameters = self.controller.Argument.parameters
    for i, v in pairs(self.chapters) do
        if checkNumber(v.id) == self.curChapterId then
            self.curIndex = i
            break
        end
    end
    ---再替换当前可领取
    if not parameters.chapterId then
        for i, v in pairs(self.chapters) do
            if questConfMgr:IsCanDrawChapterReward(v.id) then
                ----当前无奖励可领取
                self.curChapterId = checkNumber(v.id)
                self.curIndex = i
                break
            end
        end
    end
    local isUnlockChapter = parameters.isUnlockChapter
    if isUnlockChapter then
        parameters.isUnlockChapter = nil
        ---@type GuideComponent
        local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
        guideComponent:CheckLoopGuideActiveCondition(Constants.GuideModule.UnlockChapter, self.curIndex)
    end

end

function UIMainBattleChapterRewardPopupDialog:FreshCgView()
    self.cgData = {}
    ---cg列表的刷新
    ---@type TableML.TableFileRow
    local row = CfUtils.GetCfLine(CGSettingIDGroup, self.curChapterId)
    local ids = parse_strings(row:Get("ids"), ',')
    for i, id in pairs(ids) do
        table.insert(self.cgData, CfUtils.GetCfLine(CGSettingID, id))
    end
    if #self.cgData > 0 then
        local len = #self.cgData
        local pageNo = math.floor((len + 5) / 6)
        for i = len + 1, pageNo * 6 do
            table.insert(self.cgData, { isEmpty = true })
        end
        if self.ListContent.IsListViewInit then
            GameUtils.ReloadData(self.ListContent, 0)
            self.ListContent.DisplayItemNumber = 0
            GameUtils.ReloadData(self.ListContent, #self.cgData)
        else
            self.ListContent:InitGridView(#self.cgData, Bind(self, self.OnGetGridViewCellByIndex))
        end
        local progress = 0
        local count = 0
        ---@type TableML.TableFile
        local tableFile = CfUtils.GetCfTable(CGSettingID)
        for k, trow in pairs(tableFile) do
            local unlockNum = checkNumber(trow:Get("unlockNum"))
            local isUnlock = QuestConfMgr:GetInstance():IsPassQuest(unlockNum)
            if isUnlock then
                progress = progress + 1
            end
            count = count + 1
        end
        local pro = checkInt(progress * 1.0 / count * 100)
        CfUtils.FillText(self.ProgressTextNumber, string.format("%d", pro) .. string.format_size_tag("%", 24))
    end

end

---OnGetGridViewCellByIndex
---@param listView SuperScrollView.LoopGridView
---@param idx number
function UIMainBattleChapterRewardPopupDialog:OnGetGridViewCellByIndex(listView, idx)
    if idx < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local position = idx + 1
    local data = self.cgData[position]
    ---@type ChapterRewardCgCellNode
    local scr = CfUtils.GetLuaScr(cell.gameObject, ChapterRewardCgCellNodePath)
    if scr then
        scr:FreshUI(data, position)
        scr:SetCellCallbackAction(Bind(self, self.OnCgCellAction))
        if listView.DisplayItemNumber < listView.DisplayItemCount then
            scr:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            scr:PlayAnimByIdle()
        end
    end
    return cell
end

function UIMainBattleChapterRewardPopupDialog:OnCgCellAction(data, position)
    if isSet(data, "isEmpty") then
        return
    end
    self.selectData = data
    local isUnlock = QuestConfMgr:GetInstance():IsPassQuest(data.unlockNum)
    if not isUnlock then
        GameUtils.Toast(GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PassQuest, data.unlockNum))
        return
    end
    print("--->>", table.dump(data, false, 2))
    if checkNumber(data.cgType) == CG_TYPE.Picture then
        CfUtils.SetActive(self.ControlTrans:Find("Menu/BtnPlay"), true)
        ---直接播放剧情
        if self.isPlayPlot then
            return
        end
        self.isPlayPlot = true
        UINavigationBarRoot.Instance:SetActive(false)
        --显示cg图的逻辑
        ---@type Engine.UI.RawImageAlterable
        local imageAlterable = self.ImgCgDetails.transform:GetComponent(typeof(RawImageAlterable))
        CfUtils.SetActive(self.ImgCgDetails.transform.parent.gameObject, true)
        if imageAlterable then
            imageAlterable.OnFinish = function()
                print("--->>finish")
            end
            imageAlterable.IsAutoAlpha = true
            imageAlterable:LoadSprite(data.cg)
        end
        if self.co then
            cs_coroutine.stop(self.co)
            self.co = nil
        end
        self.co = cs_coroutine.start(function()
            ---开始显示cg图的逻辑
            while not self.startPlaying do
                coroutine.yield()
            end
            coroutine.yield(Yielders.GetWaitForSeconds(0.3))
            local cacheTimelineLoader = nil
            ChapterUtils.ProcessChapter(data.plotId, function(go)
                self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
                URPCameraController:SetMainCameraActive(false)
                self._plotGo = go

                -- 如果下一段是timeline剧情，预加载一下
                local vo = ChapterUtils.GetChapterGeneralVo(data.plotId)
                if vo and not string.isEmpty(vo.timelinePath) then
                    cacheTimelineLoader = ResourceModule.LoadBundleAsync(vo.timelinePath)
                    cacheTimelineLoader:Retain()
                    -- print("[加载] 预加载", checkNumber(plotIds[self.curPlotIndex + 1]), vo.timelinePath)
                end
            end, function()
                --所有的播完结束
                self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
                URPCameraController:SetMainCameraActive(true)
                UINavigationBarRoot.Instance:SetActive(true)
                KTool.SafeDelete(self._plotGo)
                CfUtils.SetActive(self.ImgCgDetails.transform.parent.gameObject, false)
                -- 释放预加载的引用
                if cacheTimelineLoader then
                    cacheTimelineLoader:Release()
                    -- print("[加载] 释放预加载", checkNumber(plotIds[self.curPlotIndex]), vo.timelinePath)
                end
                self.isPlayPlot = false
                self.startPlaying = false
            end, nil, function()
                -- 每段剧情之间加一个黑幕
                GameUtils.ShowBlackDuration(0.4, 0.3, 0.4)
                coroutine.yield(Yielders.GetWaitForSeconds(0.4))
            end)
        end)
    elseif checkNumber(data.cgType) == CG_TYPE.Movie then
        UIModule.OpenDialog(UIArgs(Constants.UITypeIds.MoviePreviewDialog, { moviePath = data.video }))
    elseif checkNumber(data.cgType) == CG_TYPE.OnlyPicture then
        ---只展示图片的逻辑
        UINavigationBarRoot.Instance:SetActive(false)
        CfUtils.SetActive(self.ControlTrans:Find("Menu/BtnPlay"), false)
        --显示cg图的逻辑
        ---@type Engine.UI.RawImageAlterable
        local imageAlterable = self.ImgCgDetails.transform:GetComponent(typeof(RawImageAlterable))
        CfUtils.SetActive(self.ImgCgDetails.transform.parent.gameObject, true)
        if imageAlterable then
            imageAlterable.OnFinish = function()
                print("--->>finish")
            end
            imageAlterable.IsAutoAlpha = true
            imageAlterable:LoadSprite(data.cg)
        end
    end
end

---FreshFinalChapterReward
---刷新最终章节的奖励
function UIMainBattleChapterRewardPopupDialog:FreshFinalChapterReward()
    local chapterVos = QuestConfMgr:GetInstance():GetAllChapterVos()
    ---@type ChapterVo
    local vo = table.takeLast(chapterVos)
    local position = #chapterVos
    CfUtils.FillText(self.FinalRewardTips:Find("TextDesc"), vo.name)
    if vo.headRewardId > 0 then
        local playerHeadNode = self.FinalRewardTips:Find("CommonPlayerHeadNode")
        if playerHeadNode then
            ---@type CommonPlayerHeadNode
            local headEnv = CfUtils.GetLuaScr(playerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
            if headEnv then
                headEnv:SetCallBack(function()
                    self.curChapterId = checkNumber(vo.id)
                    self.curIndex = position
                    self.ChapterListView:RefreshAllShownItem()
                    self:FillSelf(true)
                end)
                ---@type GoodsVo
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.headRewardId)
                if goodsVo then
                    --种类区分：1头像2头像框3徽章4主题
                    if checkNumber(goodsVo.kind) == 1 then
                        headEnv:FreshHeadIcon(vo.headRewardId, true)
                    elseif checkNumber(goodsVo.kind) == 2 then
                        headEnv:FreshFrame(vo.headRewardId, true)
                    end
                else
                    CfUtils.SetActive(self.FinalRewardTips, false)
                end
            end
        end
    else
        CfUtils.SetActive(self.FinalRewardTips, false)
    end
end

---FreshCGPanel
---刷新cg面板
function UIMainBattleChapterRewardPopupDialog:FreshCGPanel()
    ---@type ChapterVo
    local vo = QuestConfMgr:GetInstance():GetChapterVoByID(self.curChapterId)
    CfUtils.FillText(self.TextNumber, string.format('%0.2i', vo.number))
    local titleName = string.gsub(vo.name, "\\n", " ")
    CfUtils.FillText(self.TextTitle, titleName)
    local isPass = QuestConfMgr:GetInstance():IsUnlockChapter(self.curChapterId)
    CfUtils.SetActive(self.TextDesc, isPass)
    CfUtils.FillText(self.TextDesc, vo.description)
    ---刷新最终章节的奖励
    local rewards = parse_rewards(vo.chapterRewardId, vo.chapterRewardNum1)
    CfUtils.SetActive(self.CommonGoodsListLight, #rewards > 0)
    ---领取按钮的逻辑
    ----是否已领取过
    local isDrawFinish = QuestConfMgr:GetInstance():IsDrawChapterReward(self.curChapterId)
    if #rewards > 0 then
        ---@type CommonGoodsListLight
        local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, 'Game.Behaviours.CommonGoodsListLight')
        if scr then
            scr:FreshBaseUI(rewards, nil, isDrawFinish)
        end
    end
    CfUtils.SetActive(self.BtnArrowLeft, not (self.curIndex <= 1))
    CfUtils.SetActive(self.BtnArrowRight, not (self.curIndex >= #self.chapters))
    CfUtils.SetActive(self.BtnReceive, not isDrawFinish)
    if not isDrawFinish then
        local canDraw = QuestConfMgr:GetInstance():IsCanDrawChapterReward(self.curChapterId)
        CfUtils.SetActive(self.BtnReceive:Find("Lock"), not canDraw)
        CfUtils.SetActive(self.BtnReceive:Find("Unlock"), canDraw)
        if canDraw then
            CfUtils.SetActive(self.BtnReceive:Find("Unlock/redPoint"), canDraw)
        end
    end
    self:FreshCgView()
end

function UIMainBattleChapterRewardPopupDialog:FillSelf(isMoving)
    if isNull(isMoving) then
        isMoving = true
    end
    if self._isInit then
        GameUtils.ReloadData(self.ChapterListView, #self.chapters)
    else
        self.ChapterListView:InitListView(#self.chapters, Bind(self, self.OnGetCellByIndex))
        self.ChapterListView:UpdateDisplayItemCount("Cell")
        self._isInit = true
    end
    if isMoving then
        if self.curIndex > 4 then
            self.ChapterListView:MovePanelToItemIndex(self.curIndex - 4)
        else
            self.ChapterListView:MovePanelToItemIndex(0)
        end
    end
    self:FreshFinalChapterReward()
    self:FreshCGPanel()
end

---OnGetCellByIndex
---@param listView SuperScrollView.LoopListView2
---@param index number
function UIMainBattleChapterRewardPopupDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local position = index + 1
    local data = self.chapters[position]
    local cell = listView:NewListViewItem("Cell")
    ---@type UIMainBattleChapterRewardPopupNode
    local scr = CfUtils.GetLuaScr(cell.gameObject, UIMainBattleChapterRewardPopupNodePath)
    if scr then
        scr:Refresh(data, self.controller.goodIds, self.CommonGoodsListLight.gameObject, position, self.maxChapterNo)
        scr:SetSelected(position == self.curIndex)
        scr:SetCallbackAction(Bind(self, self.OnChapterCellAction))
        if listView.DisplayItemNumber < listView.DisplayItemCount then
            scr:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            scr:PlayAnimByIdle()
        end
    end
    return cell
end

---OnChapterCellAction
---@param vo ChapterVo
function UIMainBattleChapterRewardPopupDialog:OnChapterCellAction(vo, position)
    self.curChapterId = checkNumber(vo.id)
    self.curIndex = position
    self.ChapterListView:RefreshAllShownItem()
    self:FillSelf(false)
end

function UIMainBattleChapterRewardPopupDialog:OnFocus(focus)
    if focus then
        GameUtils.RefreshTopGoods(Constants.UITypeIds.UIMainBattleChapterRewardPopupDialog)
    end
end

function UIMainBattleChapterRewardPopupDialog:OnShow()
    --- @type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FillSelf(true)
    end))
    return coWait
end

function UIMainBattleChapterRewardPopupDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        SetButtonAction(self.BtnClose, function()
            UIModule.CloseDialog(self.controller)
        end)

        SetButtonAction(self.ClickClose, function()
            UIModule.CloseDialog(self.controller)
        end)
    end))
    return coWait
end

function UIMainBattleChapterRewardPopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.co then
            cs_coroutine.stop(self.co)
            self.co = nil
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        ---清理配表
        SettingModule.RemoveFileCacheByPath(CGSettingID)
        SettingModule.RemoveFileCacheByPath(CGSettingIDGroup)
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIMainBattleChapterRewardPopupDialog
